(()=>{'use strict';const input=document.querySelector('#guide-query');if(!input)return;const groups=[...document.querySelectorAll('.directory-group')];const status=document.querySelector('[data-search-status]');input.addEventListener('input',()=>{const query=input.value.toLowerCase().trim();let count=0;for(const group of groups){let matches=0;for(const card of group.querySelectorAll('[data-guide-title]')){const show=!query||query.split(/\s+/).every(word=>card.dataset.guideTitle.includes(word));card.hidden=!show;if(show)matches++;}group.hidden=matches===0;count+=matches;}status.textContent=query?`${count} ${count===1?'guide':'guides'} found${count?'':'. Try a broader topic such as gifts or headsets.'}`:'';});})();
